#pragma once
#include <emscripten/wasmfs.h>
#include <fstream>
#include <string>
#include <set>
#include <fcntl.h>
#include <unistd.h>

// Manifest is generated by the launcher, not game scripts. This is an isolated,
// read-only archive tree; saves and engine overrides continue to live in OPFS.
inline bool mountStreamedArchives(const char* manifest)
{
    std::ifstream input(manifest);
    std::string base, path;
    if (!std::getline(input, base) || base.find_first_of("\r\n\t ") != std::string::npos ||
        (base.rfind("http://", 0) != 0 && base.rfind("https://", 0) != 0)) return false;
    const auto backend = wasmfs_create_fetch_backend(base.c_str(), 16 * 1024 * 1024);
    if (wasmfs_create_directory("/stream", 0777, backend) != 0) return false;
    std::set<std::string> directories;
    size_t count = 0;
    while (std::getline(input, path))
    {
        if (++count > 4096 || path.empty() || path.front() == '/' || path.find("..") != std::string::npos ||
            path.find_first_not_of("abcdefghijklmnopqrstuvwxyz0123456789_./-") != std::string::npos) return false;
        const auto slash = path.find('/');
        if (slash == std::string::npos || slash == 0 || path.find('/', slash + 1) != std::string::npos) return false;
        const auto directory = "/stream/" + path.substr(0, slash);
        if (directories.insert(directory).second && wasmfs_create_directory(directory.c_str(), 0777, backend) != 0) return false;
        const auto file = "/stream/" + path;
        // O_CREAT instantiates fetch metadata only; no game bytes are fetched.
        const int fd = open(file.c_str(), O_CREAT | O_RDONLY, 0444);
        if (fd < 0) return false;
        close(fd);
    }
    return input.eof() && count > 0;
}
